"""Griffin boss art (your "adult gryphon" set). All frames face left.
fly: wing-stroke loop.  attack: tucks its wings, crackles with golden lightning and lets a bolt fly.
death: folds up and crumbles into golden dust."""
import base64
import math
import random
import zlib
import pygame

GRY_W, GRY_H = 95, 72
GRY_AX, GRY_AY = 54, 34                 # body centre inside a frame
GRY = {'fly': (17, ''),
       'attack': (17, ''),
       'death': (13, '')}
GRY_BEAK = [(-35, 3), (-35, 4), (-35, 5), (-35, 3), (-35, 2), (-35, 2), (-35, 3), (-35, 2), (-35, 1), (-35, 0), (-35, -1), (-35, -1), (-35, -1), (-35, -1), (-54, 5), (-54, 4), (-47, 0)]                             # beak offset from the body centre in each attack frame (1x)
WING_PTS = {2: [(32, 23), (36, 22), (41, 22), (45, 22), (50, 22), (54, 24)]}   # (kept for older callers)
FEATHER_ROWS = (0, 1, 1, 2, 2, 2, 2, 2, 1, 1, 1, 0)
GCACHE = {}
SCALE = 2


def gry_frame(name, i, scale=SCALE, tint=None):
  """(surface, anchor_x, anchor_y) for frame i of 'fly' / 'attack' / 'death'."""
  n, data = GRY[name]
  i = max(0, min(n - 1, int(i))) if name == 'death' else int(i) % n
  k = (name, i, scale, tint)
  hit = GCACHE.get(k)
  if hit is None:
    if tint:
      s0, ax, ay = gry_frame(name, i, scale)
      s = s0.copy()
      s.fill((150, 0, 0) if tint == "red" else (110, 110, 130), special_flags=pygame.BLEND_RGB_ADD)
      hit = GCACHE[k] = (s, ax, ay)
      return hit
    raw = GCACHE.get((name, 'raw'))
    if raw is None:
      raw = GCACHE[(name, 'raw')] = zlib.decompress(base64.b64decode(data))
    m = GRY_W * GRY_H * 4
    s = pygame.image.frombuffer(raw[i * m:(i + 1) * m], (GRY_W, GRY_H), 'RGBA').copy()
    if scale != 1:
      s = pygame.transform.scale(s, (GRY_W * scale, GRY_H * scale))
    hit = GCACHE[k] = (s, GRY_AX * scale, GRY_AY * scale)
  return hit


def griffin_frames():
  """flight frames (for the bestiary)"""
  return [gry_frame('fly', i)[0] for i in range(GRY['fly'][0])]


def griffin_beak(b):
  """screen position of the beak while attacking"""
  fi = b.get('fi') or 0
  bx, by = GRY_BEAK[min(13, max(0, fi))] if b.get('anim') == 'attack' else (-35, 2)
  return b['x'] + 50 + bx * SCALE, b['y'] + 50 + by * SCALE


def feather_sprite(theta):
  b = int(round(math.degrees(theta) / 15.0)) % 24
  k = ("fe", b)
  s = GCACHE.get(k)
  if s is None:
    f = pygame.Surface((12, 5), pygame.SRCALPHA)
    for x, h in enumerate(FEATHER_ROWS):
      for y in range(2 - h, 3 + h):
        f.set_at((x, y), (18, 26, 46) if (abs(y - 2) == h and h > 0) else (44, 66, 104))
      if 1 <= x <= 8:
        f.set_at((x, 2), (150, 184, 220))
    f.set_at((9, 2), (238, 230, 214))
    f.set_at((10, 2), (238, 230, 214))
    f.set_at((0, 2), (210, 226, 244))
    f = pygame.transform.scale(f, (24, 10))
    s = GCACHE[k] = pygame.transform.rotate(f, -b * 15.0 - 180)
  return s


def draw_feather(surface, p):
  s = feather_sprite(math.atan2(p.get('vy', 0), p.get('vx', -1)))
  surface.blit(s, (int(p['x'] - s.get_width() / 2), int(p['y'] - s.get_height() / 2)))


def draw_gust_waves(surface, waves):
  for w in waves:
    h = int(w['h'])
    for wd, col in ((8, (110, 160, 214)), (5, (196, 224, 248)), (2, (255, 255, 255))):
      pygame.draw.arc(surface, col, (int(w['x'] - 22), int(w['y'] - h), 44, h * 2), 1.92, 4.36, wd)
    for k in range(5):
      yy = int(w['y'] - h * 0.8 + k * h * 0.4)
      pygame.draw.line(surface, (232, 244, 255), (int(w['x'] + 14), yy), (int(w['x'] + 14 + 30 + k * 5), yy), 2)


def draw_lightning(surface, x0, y, x1, t):
  """the griffin's golden bolt: a few jagged strands from its beak to the left edge"""
  rnd = random.Random(int(t) // 2)
  for strand, (col, w) in enumerate((((255, 196, 40), 7), ((255, 236, 120), 4), ((255, 255, 240), 2))):
    pts, x = [], x0
    yy = y
    while x > x1:
      pts.append((int(x), int(yy)))
      x -= rnd.randint(18, 34)
      yy = y + rnd.randint(-9, 9) * (1 if strand < 2 else 0.5)
    pts.append((int(x1), int(y)))
    if len(pts) > 1:
      pygame.draw.lines(surface, col, False, pts, w)
  for _ in range(4):                                    # little forks
    fx = rnd.randint(int(x1) + 20, int(x0) - 10) if x0 - x1 > 40 else x0
    pygame.draw.line(surface, (255, 230, 110), (fx, y), (fx - rnd.randint(10, 24), y + rnd.choice((-1, 1)) * rnd.randint(10, 22)), 2)


def draw_griffin_boss(surface, b):
    atk = b.get('atk', 'idle')
    anim = b.get('anim', 'fly')
    fi = b.get('fi') or 0
    if b.get('state') == 'dying':
      anim, fi = 'death', min(12, b.get('dt', 0) // 4)
    tint = None
    if b.get('flash') and b['flash'] > 0 and anim != 'death':
      tint = "red" if atk in ("dive_warn", "thunder") else "white"
    spr, ax, ay = gry_frame(anim, fi, SCALE, tint)
    cx, cy = int(b['x']) + 50, int(b['y']) + 50
    if b.get('tilt'):
      spr = pygame.transform.rotate(spr, b['tilt'])
      ax, ay = spr.get_width() // 2, spr.get_height() // 2
    if b.get('alpha', 255) < 255:
      spr = spr.copy()
      spr.set_alpha(max(0, b['alpha']))
    surface.blit(spr, (cx - ax, cy - ay))
    bx, by = int(b['x']), int(b['y'])
    if atk == "dive_warn" and b['at'] % 10 < 6:
      pygame.draw.polygon(surface, (255, 50, 40), [(bx + 50, by - 46), (bx + 72, by - 8), (bx + 28, by - 8)])
      pygame.draw.polygon(surface, (255, 255, 255), [(bx + 50, by - 46), (bx + 72, by - 8), (bx + 28, by - 8)], 2)
      pygame.draw.rect(surface, (255, 255, 255), (bx + 48, by - 34, 5, 14))
      pygame.draw.rect(surface, (255, 255, 255), (bx + 48, by - 16, 5, 5))
    if atk == "thunder" and b.get('lock') is not None and b.get('bolt', 0) <= 0 and b['at'] % 6 < 4:   # where the bolt will strike
      ly = int(b['lock'])
      for x in range(int(griffin_beak(b)[0]) - 10, 0, -26):
        pygame.draw.line(surface, (255, 214, 80), (x, ly), (x - 12, ly), 2)
    if b.get('bolt', 0) > 0:
      x0, y0 = griffin_beak(b)
      draw_lightning(surface, x0, b['lock'], -10, b['bolt'] + b['at'])
    if b.get('stun', 0) > 0:
      for k in range(3):
        a = b['at'] * 0.25 + k * 2.1
        pygame.draw.circle(surface, (255, 230, 60), (int(bx + 40 + math.cos(a) * 26), int(by - 16 + math.sin(a) * 6)), 4)
    draw_gust_waves(surface, b.get('waves', []))


def draw_griffin(surface, x, y, anim):
  spr, ax, ay = gry_frame('fly', int(anim * 6))
  surface.blit(spr, (int(x) + 50 - ax, int(y) + 50 - ay))
